fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, open Data Explorer, then the Dashboards section. Click the 'New' button to open its dropdown (it offers 'Dashboard' and 'Category'), then choose 'Category'. A 'Create Category' dialog should appear with a required Name field and an optional Description field, plus Create and Cancel buttons. Enter a category name like 'CU Test Folder' and click Create, then confirm the new category folder appears in the browser. Success is the create-category dialog rendering and the new folder showing up after creating. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
